export const getSpeakingSet=(id:string)=>speakingSets.find(set=>set.id===id)
export const getScene=(set:SpeakingSet,id:string)=>set.scenes.find(scene=>scene.id===id)
export function validateSpeakingSets():string[]{
 const issues:string[]=[]
 const ids=new Set<string>()
 for(const s of speakingSets){
  if(ids.has(s.id))issues.push('Tekrarlı set: '+s.id);ids.add(s.id)
  if(s.themes.length!==6||s.scenes.length!==3)issues.push(s.id+': 6 tema veya 3 özgün görsel eksik')
  for(const c of s.scenes) {
   if(ids.has(c.id))issues.push('Tekrarlı sahne: '+c.id);ids.add(c.id)
   if(c.prompts.length!==3||!c.example||!c.people||!c.place||!c.actions)issues.push(c.id+': sahne bilgileri eksik')
  }
 }
 return issues
}

import {describe,expect,it} from 'vitest'
import {getSpeakingSet,phraseBank,speakingSets,validateSpeakingSets} from './content'
import {durationText,finishSession,makeAttempt,makeSession,recordingId,remainingSeconds,toggleTopic} from './model'
describe('Özgün ZA1 Sprechen görevleri',()=>{
 it('2 tam set, 6 farklı çizim konusu, 3 görev ve 3 turlu rol oyunu var',()=>{
  expect(speakingSets).toHaveLength(2);expect(validateSpeakingSets()).toEqual([])
  for(const s of speakingSets){expect(s.themes).toHaveLength(6);expect(s.scenes).toHaveLength(3);
   for(const scene of s.scenes)expect(scene.prompts).toHaveLength(3)}
  expect(getSpeakingSet('sprechen-unterwegs-02')?.scenes[2].title).toContain('Feier')
 })
 it('3 aşamada kullanılabilir konuşma kalıpları var',()=>{
  for(const p of [1,2,3] as const)expect(phraseBank[p].length).toBeGreaterThan(4)
 })
 it('toplam 4 kişisel konu seçilebilir',()=>{
  let s=makeSession(speakingSets[0],'practice',100)
  for(const id of speakingSets[0].themes.map(x=>x.id))s=toggleTopic(s,id)
  expect(s.selectedTopics).toHaveLength(4)
  s=toggleTopic(s,s.selectedTopics[0]);expect(s.selectedTopics).toHaveLength(3)
 })
 it('yaklaşık 10 dakika timer gerçek saat üzerinden sürer',()=>{
  const s=makeSession(speakingSets[0],'timed',1000000)
  expect(remainingSeconds(s,1000000)).toBe(600)
  expect(remainingSeconds(s,1060000)).toBe(540)
  expect(remainingSeconds(s,2000000)).toBe(0)
  expect(durationText(65)).toBe('01:05')
 })
 it('kayıt anahtarları göreve göre farklıdır',()=>{
  const s=makeSession(speakingSets[0],'practice',100)
  expect(recordingId(s.id,1)).not.toEqual(recordingId(s.id,2))
 })
 it('tamamlanan konuşmaya puan uydurulmaz',()=>{
  const s=finishSession(makeSession(speakingSets[0],'practice',1000000),1300000)
  const a=makeAttempt(s)
  expect(a).not.toHaveProperty('correctCount')
  expect(a.finishedAt).toBeDefined()
 })
})

import type { SpeakingMode, SpeakingPart, SpeakingSet } from './content'
export const SPEAKING_SECONDS=10*60
export interface SpeakingSession {
 id:string;module:'sprechen';setId:string;mode:SpeakingMode;startedAt:string;updatedAt:string;
 endsAt?:string;finishedAt?:string;currentPart:SpeakingPart;
 selectedTopics:string[];sceneId:string;roleplayStep:number;
 notes:Partial<Record<SpeakingPart,string>>;
 selfChecks:Partial<Record<SpeakingPart,string[]>>;
 recordings:Partial<Record<SpeakingPart,{id:string;duration:number;size:number;mime:string;createdAt:string}>>;
}
export interface LocalRecording {
 id:string;sessionId:string;part:SpeakingPart;createdAt:string;mime:string;duration:number;
 blob:Blob
}
export const recordingId=(sessionId:string,part:SpeakingPart)=>sessionId+':recording:'+part
export const durationText=(seconds:number)=>String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0')
export function makeSession(set:SpeakingSet,mode:SpeakingMode,at=Date.now()):SpeakingSession{
 const date=new Date(at).toISOString()
 return {id:'sprechen:'+set.id+':'+mode+':session:'+at,module:'sprechen',setId:set.id,mode,
 startedAt:date,updatedAt:date,endsAt:mode==='timed'?new Date(at+SPEAKING_SECONDS*1000).toISOString():undefined,
 currentPart:1,selectedTopics:[],sceneId:'',roleplayStep:0,notes:{},selfChecks:{},recordings:{}}
}
export function remainingSeconds(s:SpeakingSession,now=Date.now()):number{
 return !s.endsAt||s.finishedAt?SPEAKING_SECONDS:Math.max(0,Math.ceil((new Date(s.endsAt).getTime()-now)/1000))
}
export function toggleTopic(s:SpeakingSession,id:string):SpeakingSession{
 const next=s.selectedTopics.includes(id)?s.selectedTopics.filter(x=>x!==id):s.selectedTopics.length<4?[...s.selectedTopics,id]:s.selectedTopics
 return {...s,selectedTopics:next,updatedAt:new Date().toISOString()}
}
export function setPart(s:SpeakingSession,part:SpeakingPart):SpeakingSession{
 return {...s,currentPart:part,updatedAt:new Date().toISOString()}
}
export function finishSession(s:SpeakingSession,at=Date.now()):SpeakingSession{
 return {...s,finishedAt:new Date(at).toISOString(),updatedAt:new Date(at).toISOString()}
}
export function makeAttempt(s:SpeakingSession){
 return {id:s.id+':completed',module:'sprechen' as const,taskId:s.setId,
 mode:s.mode==='practice'?'practice' as const:'exam' as const,
 startedAt:s.startedAt,updatedAt:s.updatedAt,finishedAt:s.finishedAt,
 answers:[],
 speaking:{sessionId:s.id,selectedTopics:s.selectedTopics,sceneId:s.sceneId,recordingCount:Object.keys(s.recordings).length}}
 // No automatic pronunciation or success score.
}
export const selectedComplete=(s:SpeakingSession)=>s.selectedTopics.length===4

import {describe,it,expect} from 'vitest'
import {DB_VERSION,STORE_NAMES,missingStores} from './db'
describe('IndexedDB v1 -> v2 geçişi',()=>{
 it('mevcut depolar yeniden oluşturulmaz veya silinmez',()=>{
  expect(DB_VERSION).toBe(2)
  const previous=['meta','attempts','drafts','progress','sessions','recordings','teacherRequests']
  expect(missingStores(previous)).toEqual(['examSessions'])
 })
 it('tüm depolar varsa göç işlemi yoktur',()=>expect(missingStores([...STORE_NAMES])).toEqual([]))
